import { test, expect } from '@playwright/test';

test.describe('500 Error Page Display', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dashboard');
  });

  test('should display error page when server returns 500 error', async ({ page }) => {
    // Setup intercept to simulate 500 error
    await page.route('**/api/data', (route) => {
      route.abort('failed');
    });

    // Attempt to load data
    const dataButton = page.getByRole('button', { name: /load data/i });
    await expect(dataButton).toBeVisible();
    await dataButton.click();

    // Verify error page is displayed
    const errorMessage = page.getByText(/unexpected error/i);
    await expect(errorMessage).toBeVisible();

    const retryButton = page.getByRole('button', { name: /retry/i });
    await expect(retryButton).toBeVisible();

    // Verify error page has correct title
    const errorTitle = page.getByText(/500 Internal Server Error/i);
    await expect(errorTitle).toBeVisible();

    // Verify error page has descriptive message
    const errorDescription = page.getByText(/failed to load data due to server error/i);
    await expect(errorDescription).toBeVisible();

    // Verify error page has navigation options
    const backButton = page.getByRole('button', { name: /back/i });
    await expect(backButton).toBeVisible();

    const homeButton = page.getByRole('button', { name: /home/i });
    await expect(homeButton).toBeVisible();

    // Verify error page has status code displayed
    const statusCode = page.getByText(/500/i);
    await expect(statusCode).toBeVisible();

    // Verify error page has a timestamp
    const timestamp = page.getByText(/at \d{2}:\d{2}:\d{2}/i);
    await expect(timestamp).toBeVisible();

    // Verify error page has a stack trace (if available)
    const stackTrace = page.getByText(/stack trace/i);
    await expect(stackTrace).toBeVisible();

    // Verify error page has a retry button
    await expect(retryButton).toBeVisible();

    // Verify error page has a close button
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    // Verify error page is not accessible by direct URL
    const errorPageUrl = page.url();
    expect(errorPageUrl).toContain('/error');
  });

